import csv
from pathlib import Path
root='https://help.autodesk.com/view/fusion360/ENU/'
rows=[]
def group(space,category,priority,source,data):
 for pair in data.strip().split('|'):
  es,en=pair.strip().split('=',1)
  id=f'GC-{len(rows)+1:04d}'
  done=space=='Sólido' and en in ['Box','Cylinder','Sphere','Boolean union','Boolean cut','Boolean intersection']
  rows.append([id,es,en,space,category,f'{es}: capacidad objetivo; opciones detalladas pendientes de inventario.' if not done else 'Operación B-Rep básica mediante OCCT; sin interacción gráfica.',priority,'Alta' if priority in ['P0','P3'] else 'Por evaluar', 'OCCT; documentos; UI' if space in ['Sólido','Superficie','Construcción','Ensamblaje'] else 'Por determinar','Por evaluar','En pruebas' if done else 'No iniciada','Prueba local aprobada (alcance básico)' if done else 'No iniciada','No iniciada',source,'0.1.0-alpha.1' if done else 'Pendiente','Linux, solo casos básicos; Windows y UI pendientes' if done else 'Inventario inicial; referencia de comando y variantes por auditar'])
