for r in rows:
 if r[2] in ['B-Rep validation','Mass properties']:
  r[10]='En pruebas';r[11]='Prueba local aprobada (alcance básico)';r[14]='0.1.0-alpha.1';r[15]='No integrado; pruebas básicas Linux'
 if r[2] in ['Persistent topological naming']:
  r[10]='En investigación';r[11]='Experimento de historia ejecutado; resolución pendiente'
 if r[2].startswith('Boolean'):r[6]='P0'
 if r[2] in ['Create Form','Gear','Shaft','Thread','Volumetric Lattice','Pattern on Path']:r[6]='P2'
