 w=csv.writer(f,lineterminator="\n");w.writerow('id,nombre_es,nombre_en,espacio,categoria,descripcion,prioridad,complejidad,dependencias,riesgo,estado,pruebas,interfaz,referencia,version,limitaciones'.split(','));w.writerows(rows)
